def seed_tariffs(apps, schema_editor):
    Student = apps.get_model('core', 'Student')
    Tariff = apps.get_model('core', 'StudentTariff')
    alias = schema_editor.connection.alias
    current = django.utils.timezone.localdate().replace(day=1)
    following = date(current.year + (current.month == 12), current.month % 12 + 1, 1)
    for student in Student.objects.using(alias).select_related('group').iterator():
        group = student.group
        discount = min(100, max(0, student.discount_percent))
        fee = max(Decimal('0'), group.monthly_fee * (100 - Decimal(discount)) / 100) if group else Decimal('0')
        # Old records have no historical prices: preserve today's calculation,
        # explicitly mark the initial assumption rather than inventing history.
        Tariff.objects.using(alias).create(
            student_id=student.pk, effective_month=student.registration_date.replace(day=1),
            fee=fee, billing_enabled=bool(group), group_id_snapshot=student.group_id,
            group_name=group.name if group else '', is_estimated=True,
        )
        if group and student.status != 'active' and student.registration_date.replace(day=1) < following:
            Tariff.objects.using(alias).create(
                student_id=student.pk, effective_month=following, fee=0,
                billing_enabled=False, group_id_snapshot=student.group_id,
                group_name=group.name, is_estimated=False,
            )
    Audit = apps.get_model('core', 'FinancialAudit')
    for name in ('Payment', 'ReceptionistCommission', 'Salary', 'ReceptionistSalary', 'Expense', 'StudentTariff'):
        model = apps.get_model('core', name)
        batch = []
        for instance in model.objects.using(alias).iterator():
            values = {field.attname: getattr(instance, field.attname) for field in model._meta.concrete_fields}
            batch.append(Audit(entity=model._meta.model_name, object_id=instance.pk, action='opening',
                               actor_name='Yangilash paytidagi boshlang‘ich yozuv',
                               before={}, after=json.loads(json.dumps(values, cls=DjangoJSONEncoder))))
            if len(batch) == 500:
                Audit.objects.using(alias).bulk_create(batch)
                batch = []
        if batch:
            Audit.objects.using(alias).bulk_create(batch)


